import React, { useMemo } from "react"
import styled from "styled-components"
import { Link } from "gatsby"

import { groupPostsBySeries, latestPost } from "utils/seriesRules"

const Section = styled.section`
  margin-top: 36px;
  padding-top: 28px;
  padding-bottom: 28px;
  border-top: 1px solid ${props => props.theme.colors.dividerSoft};
  border-bottom: 1px solid ${props => props.theme.colors.dividerSoft};
`

const Header = styled.div`
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 20px;
  gap: 12px;
`

const Title = styled.h2`
  margin: 0;
  font-size: 18px;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: ${props => props.theme.colors.text};
`

const Lead = styled.span`
  font-size: 13px;
  color: ${props => props.theme.colors.tertiaryText};
`

const Grid = styled.div`
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;

  @media (max-width: 700px) {
    grid-template-columns: 1fr;
  }
`

const Card = styled(Link)`
  display: flex;
  flex-direction: column;
  padding: 22px 22px 20px;
  border: 1px solid ${props => props.theme.colors.cardBorder};
  border-radius: 12px;
  background: ${props => props.theme.colors.cardBackground};
  text-decoration: none;
  color: inherit;
  transition: border-color 0.15s ease;

  &:hover {
    border-color: ${props => props.theme.colors.cardBorderHover};
  }

  &:hover h3 {
    color: ${props => props.theme.colors.accent};
  }
`

const Eyebrow = styled.div`
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 10px;
  font-size: 11.5px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: ${props => props.theme.colors.accent};
`

const Count = styled.span`
  color: ${props => props.theme.colors.tertiaryText};
  font-weight: 500;
`

const Name = styled.h3`
  margin: 0 0 6px;
  font-size: 18px;
  font-weight: 700;
  line-height: 1.35;
  letter-spacing: -0.01em;
  color: ${props => props.theme.colors.text};
  transition: color 0.15s ease;
`

const Tagline = styled.p`
  margin: 0;
  font-size: 13.5px;
  line-height: 1.55;
  color: ${props => props.theme.colors.secondaryText};
`

const Meta = styled.div`
  margin-top: 12px;
  font-size: 12px;
  color: ${props => props.theme.colors.tertiaryText};
`

const SeriesShowcase = ({ posts }) => {
  const series = useMemo(
    () =>
      // 최근에 시작한 시리즈를 앞에 둔다.
      groupPostsBySeries(posts)
        .map(group => ({ ...group, latest: latestPost(group.posts) }))
        .reverse(),
    [posts]
  )

  if (series.length === 0) return null

  return (
    <Section>
      <Header>
        <Title>Series</Title>
        <Lead>한 흐름으로 묶인 글들</Lead>
      </Header>
      <Grid>
        {series.map(({ rule, posts: seriesPosts, latest }) => {
          const target = rule.indexSlug || seriesPosts[0].fields.slug
          return (
            <Card key={rule.id} to={target}>
              <Eyebrow>
                <span>{rule.id}</span>
                <Count>· {seriesPosts.length}편</Count>
              </Eyebrow>
              <Name>{rule.name}</Name>
              <Tagline>{rule.tagline}</Tagline>
              {latest && <Meta>최근 {latest.frontmatter.date}</Meta>}
            </Card>
          )
        })}
      </Grid>
    </Section>
  )
}

export default SeriesShowcase
